def solve_full(g, flood_conn=4, halo=8, keep_component=True, paint_boundary=True):
 R,C=len(g),len(g[0]); o=[[8 if v==1 else v for v in row] for row in g]
 dirs=[(-1,0),(1,0),(0,-1),(0,1)] if flood_conn==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)]
 hdirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)] if halo==8 else [(-1,0),(1,0),(0,-1),(0,1)]
 seen=set(); q=deque()
 for r in range(R):
  for c in range(C):
   if g[r][c]==6:
    for dr,dc in dirs:
     rr,cc=r+dr,c+dc
     if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in seen: seen.add((rr,cc)); q.append((rr,cc))
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in seen: seen.add((rr,cc)); q.append((rr,cc))
 for r,c in seen:
  if r==0 or c==0 or r==R-1 or c==C-1 or any(0<=r+dr<R and 0<=c+dc<C and g[r+dr][c+dc]==1 for dr,dc in hdirs): o[r][c]=7
 # Keep complete 1-components that border visited 8, using 4-connectivity
 visited_ones=set()
 for r in range(R):
  for c in range(C):
   if g[r][c]!=1 or (r,c) in visited_ones: continue
   comp=set([(r,c)]); qq=[(r,c)]; visited_ones.add((r,c))
   while qq:
    rr,cc=qq.pop()
    for dr,dc in dirs:
     nr,nc=rr+dr,cc+dc
     if 0<=nr<R and 0<=nc<C and g[nr][nc]==1 and (nr,nc) not in visited_ones:
      visited_ones.add((nr,nc));comp.add((nr,nc));qq.append((nr,nc))
   # retain entire component iff at least one component pixel neighbors selected empty region (Moore)
   keep=any((r0+dr,c0+dc) in seen for r0,c0 in comp for dr,dc in hdirs if 0<=r0+dr<R and 0<=c0+dc<C)
   if keep:
    for rr,cc in comp:o[rr][cc]=1
 return o,seen
