def component_status(g):
 R,C=len(g),len(g[0]); dirs=[(-1,0),(1,0),(0,-1),(0,1)]; vis=set(); comps=[]
 for r in range(R):
  for c in range(C):
   if g[r][c]==1 and (r,c) not in vis:
    q=[(r,c)];vis.add((r,c));co=[]
    while q:
     a,b=q.pop();co.append((a,b))
     for dr,dc in dirs:
      x,y=a+dr,b+dc
      if 0<=x<R and 0<=y<C and g[x][y]==1 and (x,y) not in vis:vis.add((x,y));q.append((x,y))
    comps.append(co)
 return [(len(co),min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co)) for co in comps]
